#include <cuda_runtime.h>
#include <vector>
#define main legacy_main
#include "../cbsfil-cuda/main.cu"
#undef main
#define CK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(1);}}while(0)
int main(int argc,char**argv){int w=256,h=256,n=w*h,repeats=argc>1?atoi(argv[1]):20;std::vector<float>input(n),expected,got(n);for(int i=0;i<n;i++)input[i]=float((i*37+17)%257-128)/128.f;expected=input;toCoef2DX_ref(expected.data(),w*4,w,h);toCoef2DY_ref(expected.data(),w*4,w,h);float*image;CK(cudaMalloc(&image,n*4));CK(cudaMemcpy(image,input.data(),n*4,cudaMemcpyHostToDevice));auto launch=[&](){toCoef2DX<<<4,64>>>(image,w*4,w,h);toCoef2DY<<<4,64>>>(image,w*4,w,h);};launch();CK(cudaDeviceSynchronize());bool all=true;for(int trial=1;trial<=5;trial++){double elapsed=0;for(int rep=0;rep<repeats;rep++){CK(cudaMemcpy(image,input.data(),n*4,cudaMemcpyHostToDevice));CK(cudaDeviceSynchronize());auto t0=std::chrono::steady_clock::now();launch();CK(cudaDeviceSynchronize());elapsed+=std::chrono::duration<double>(std::chrono::steady_clock::now()-t0).count()/repeats;}CK(cudaMemcpy(got.data(),image,n*4,cudaMemcpyDeviceToHost));float ma=0,mr=0;bool ok=true;for(int i=0;i<n;i++){float e=fabsf(got[i]-expected[i]);ma=fmaxf(ma,e);mr=fmaxf(mr,e/fmaxf(fabsf(expected[i]),1.1920929e-7f));ok&=std::isfinite(got[i])&&e<=1e-3f;}all&=ok;char file[100];sprintf(file,"cbsfil_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(got.data(),4,n,f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%d,\"max_abs_error\":%.12g,\"max_rel_error\":%.12g,\"timing_region\":\"one_xy_recursive_prefilter_pair_reset_excluded\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%d,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",n,ma,mr,repeats,file,n);}CK(cudaFree(image));puts(all?"PASS":"FAIL");return all?0:1;}
